-- Phase 3: parties, pricing, sales, purchasing, cash
ALTER TABLE tenants ADD COLUMN vat_registered BOOLEAN NOT NULL DEFAULT false, ADD COLUMN vat_number TEXT;
ALTER TABLE products ADD COLUMN tax_rate NUMERIC(9,6), ADD COLUMN default_price NUMERIC(19,4) NOT NULL DEFAULT 0, ADD COLUMN min_price NUMERIC(19,4), ADD COLUMN max_price NUMERIC(19,4);
CREATE TABLE parties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, phone TEXT, email TEXT, tax_number TEXT, tax_classification TEXT, credit_limit NUMERIC(19,4) NOT NULL DEFAULT 0, payment_terms_days INT NOT NULL DEFAULT 0, credit_hold BOOLEAN NOT NULL DEFAULT false, price_list_id UUID, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX parties_tenant_kind_idx ON parties (tenant_id, kind);
CREATE TABLE price_lists (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE price_list_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, price_list_id UUID NOT NULL REFERENCES price_lists(id) ON DELETE CASCADE, product_id UUID NOT NULL, price NUMERIC(19,4) NOT NULL, effective_from DATE NOT NULL, effective_to DATE, UNIQUE (tenant_id, price_list_id, product_id, effective_from));
CREATE TABLE sales_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, number INT, party_id UUID, warehouse_id UUID NOT NULL, representative_id UUID, business_date DATE NOT NULL, commercial_status TEXT NOT NULL DEFAULT 'draft', inventory_status TEXT NOT NULL DEFAULT 'none', accounting_status TEXT NOT NULL DEFAULT 'unposted', payment_status TEXT NOT NULL DEFAULT 'unpaid', tax_status TEXT NOT NULL DEFAULT 'not_required', sync_status TEXT NOT NULL DEFAULT 'synced', subtotal NUMERIC(19,4) NOT NULL DEFAULT 0, discount_total NUMERIC(19,4) NOT NULL DEFAULT 0, tax_total NUMERIC(19,4) NOT NULL DEFAULT 0, total NUMERIC(19,4) NOT NULL DEFAULT 0, paid_amount NUMERIC(19,4) NOT NULL DEFAULT 0, journal_entry_id UUID, idempotency_key TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, idempotency_key), UNIQUE (tenant_id, number));
CREATE TABLE sales_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, invoice_id UUID NOT NULL REFERENCES sales_invoices(id) ON DELETE CASCADE, product_id UUID NOT NULL, lot_id UUID, qty NUMERIC(19,6) NOT NULL, free_qty NUMERIC(19,6) NOT NULL DEFAULT 0, original_price NUMERIC(19,4) NOT NULL, unit_price NUMERIC(19,4) NOT NULL, discount NUMERIC(19,4) NOT NULL DEFAULT 0, tax_rate NUMERIC(9,6) NOT NULL DEFAULT 0, tax_amount NUMERIC(19,4) NOT NULL DEFAULT 0, line_total NUMERIC(19,4) NOT NULL, unit_cost NUMERIC(19,4) NOT NULL DEFAULT 0, override_reason TEXT, override_approved_by UUID);
CREATE TABLE credit_notes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, number INT, original_invoice_id UUID NOT NULL, party_id UUID, business_date DATE NOT NULL, total NUMERIC(19,4) NOT NULL, tax_total NUMERIC(19,4) NOT NULL DEFAULT 0, journal_entry_id UUID, accounting_status TEXT NOT NULL DEFAULT 'posted', idempotency_key TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, idempotency_key));
CREATE TABLE credit_note_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, note_id UUID NOT NULL REFERENCES credit_notes(id) ON DELETE CASCADE, product_id UUID NOT NULL, warehouse_id UUID NOT NULL, qty NUMERIC(19,6) NOT NULL, unit_price NUMERIC(19,4) NOT NULL, tax_rate NUMERIC(9,6) NOT NULL DEFAULT 0, line_total NUMERIC(19,4) NOT NULL);
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, party_id UUID, direction TEXT NOT NULL, method TEXT NOT NULL, amount NUMERIC(19,4) NOT NULL, business_date DATE NOT NULL, settlement_status TEXT NOT NULL DEFAULT 'settled', journal_entry_id UUID, idempotency_key TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, idempotency_key));
CREATE TABLE payment_allocations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, payment_id UUID NOT NULL REFERENCES payments(id) ON DELETE CASCADE, document_type TEXT NOT NULL, document_id UUID NOT NULL, amount NUMERIC(19,4) NOT NULL);
CREATE TABLE supplier_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, number INT, party_id UUID NOT NULL, warehouse_id UUID NOT NULL, business_date DATE NOT NULL, accounting_status TEXT NOT NULL DEFAULT 'posted', payment_status TEXT NOT NULL DEFAULT 'unpaid', subtotal NUMERIC(19,4) NOT NULL DEFAULT 0, tax_total NUMERIC(19,4) NOT NULL DEFAULT 0, total NUMERIC(19,4) NOT NULL DEFAULT 0, paid_amount NUMERIC(19,4) NOT NULL DEFAULT 0, journal_entry_id UUID, idempotency_key TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (tenant_id, idempotency_key));
CREATE TABLE supplier_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, invoice_id UUID NOT NULL REFERENCES supplier_invoices(id) ON DELETE CASCADE, product_id UUID NOT NULL, lot_id UUID, qty NUMERIC(19,6) NOT NULL, unit_cost NUMERIC(19,4) NOT NULL, tax_rate NUMERIC(9,6) NOT NULL DEFAULT 0, tax_amount NUMERIC(19,4) NOT NULL DEFAULT 0, line_total NUMERIC(19,4) NOT NULL);
CREATE TABLE cash_accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, account_id UUID NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE expenses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, category TEXT NOT NULL, description TEXT, amount NUMERIC(19,4) NOT NULL, tax_rate NUMERIC(9,6) NOT NULL DEFAULT 0, cash_account_id UUID NOT NULL, business_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'approved', journal_entry_id UUID, attachment_url TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
DO $$ DECLARE t TEXT; BEGIN
  FOREACH t IN ARRAY ARRAY['parties','price_lists','price_list_items','sales_invoices','sales_lines','credit_notes','credit_note_lines','payments','payment_allocations','supplier_invoices','supplier_lines','cash_accounts','expenses'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id::text = current_setting(''app.tenant_id'', true) OR current_setting(''app.platform_access'', true) = ''on'') WITH CHECK (tenant_id::text = current_setting(''app.tenant_id'', true) OR current_setting(''app.platform_access'', true) = ''on'')', t);
  END LOOP;
END $$;
